/**
 * The Hostage Exchange — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { HOSTAGE_EXCHANGE_TEMPLATE } from '../hostage-exchange';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Hostage Exchange — template structure", () => {
  it('carries its identity', () => {
    expect(HOSTAGE_EXCHANGE_TEMPLATE.id).toBe('encounter.town.hostage_exchange');
    expect(HOSTAGE_EXCHANGE_TEMPLATE.reach).toBe('heart');
    expect(HOSTAGE_EXCHANGE_TEMPLATE.rarityTier).toBe(2);
    expect(HOSTAGE_EXCHANGE_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = HOSTAGE_EXCHANGE_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['hostage.loosen_guarded_tongues', 'hostage.reveal_the_price']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['light', 'mind']);
  });

  it('step 1 deals the authored hand', () => {
    const step = HOSTAGE_EXCHANGE_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['hostage.still_ready_blades', 'hostage.stand_as_surety']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['order']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(HOSTAGE_EXCHANGE_TEMPLATE.settings).toEqual(['urban', 'rural']);
    expect(HOSTAGE_EXCHANGE_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban', 'rural']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(HOSTAGE_EXCHANGE_TEMPLATE.consequenceDraw).toEqual(['relationship', 'companion']);
    expect(HOSTAGE_EXCHANGE_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.hostage_exchange',
          reach: 'heart',
          rarityTier: 2,
        }),
        HOSTAGE_EXCHANGE_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
